INSERT INTO public.career_roles (role_code, title_en, title_ar, career_family, description_en, description_ar, suitable_programmes, typical_entry_level, required_hard_skills, preferred_hard_skills, required_soft_skills, preferred_tools, preferred_courses, certifications, experience_expectations, portfolio_expectations, industry_sectors, ats_keywords, active) VALUES
('SW_ENGINEER','Software Engineer','مهندس برمجيات','software engineering','Designs, builds and maintains software applications and services.','يصمم ويطور ويصون التطبيقات والخدمات البرمجية.',ARRAY['BSc Computer Science','Computer Science','Information Systems and Security','BSc Information Systems and Security'],'entry',ARRAY['Programming','Data Structures','Algorithms','Object Oriented Programming'],ARRAY['Web Development','APIs','Databases','Testing'],ARRAY['Problem solving','Teamwork','Communication'],ARRAY['Git','Docker','VS Code','Postman'],ARRAY['Programming','Data Structures','Software Engineering','Databases'],ARRAY['AWS Certified Developer'],'One internship or two substantial software projects.','A public code portfolio with 2-3 working applications.',ARRAY['technology','banking','government'],ARRAY['software engineer','backend','frontend','full stack','git','api'],true),
('DATA_ANALYST','Data Analyst','محلل بيانات','data and analytics','Turns raw data into dashboards, reports and business insight.','يحوّل البيانات الخام إلى لوحات ومؤشرات ورؤى تدعم القرار.',ARRAY['BSc Data Science and Artificial Intelligence','Data Science','BSc Mathematical Sciences','Mathematical Sciences','Bachelor of Business Administration','Information Systems and Security'],'entry',ARRAY['SQL','Statistics','Data Visualisation','Excel'],ARRAY['Python','Data Cleaning','Reporting'],ARRAY['Analytical thinking','Attention to detail','Communication'],ARRAY['Power BI','Tableau','SQL','Excel'],ARRAY['Statistics','Databases','Data Analysis','Mathematics'],ARRAY['Microsoft Power BI Data Analyst'],'One analytics internship or coursework projects with real datasets.','Two dashboards or analysis notebooks with documented findings.',ARRAY['banking','technology','government','healthcare'],ARRAY['data analyst','sql','power bi','tableau','dashboard'],true),
('DATA_SCIENTIST','Data Scientist','عالم بيانات','data and analytics','Builds predictive models and machine learning solutions.','يبني النماذج التنبؤية وحلول تعلم الآلة.',ARRAY['BSc Data Science and Artificial Intelligence','Data Science','BSc Mathematical Sciences','BSc Computer Science'],'entry',ARRAY['Python','Machine Learning','Statistics','SQL'],ARRAY['Deep Learning','Feature Engineering','Model Evaluation'],ARRAY['Analytical thinking','Curiosity','Communication'],ARRAY['Python','Jupyter','scikit-learn','TensorFlow'],ARRAY['Machine Learning','Statistics','Linear Algebra','Programming'],ARRAY['TensorFlow Developer Certificate'],'Research assistantship, internship or applied ML projects.','Two end-to-end ML projects with evaluation metrics.',ARRAY['technology','healthcare','energy'],ARRAY['data scientist','machine learning','python','model','pandas'],true),
('AI_ENGINEER','AI / Machine Learning Engineer','مهندس ذكاء اصطناعي','artificial intelligence','Deploys and operates AI models in production systems.','ينشر ويشغّل نماذج الذكاء الاصطناعي ضمن الأنظمة الإنتاجية.',ARRAY['BSc Data Science and Artificial Intelligence','BSc Computer Science','Data Science'],'entry',ARRAY['Python','Machine Learning','APIs','Programming'],ARRAY['MLOps','Cloud Computing','Deep Learning'],ARRAY['Problem solving','Collaboration','Communication'],ARRAY['Docker','Git','AWS','Python'],ARRAY['Machine Learning','Programming','Cloud Computing'],ARRAY['AWS Certified Machine Learning'],'Internship or capstone deploying a model behind an API.','A deployed demo with documented architecture.',ARRAY['technology','government'],ARRAY['machine learning engineer','mlops','deployment','python','docker'],true),
('CYBERSECURITY_ANALYST','Cybersecurity Analyst','محلل أمن سيبراني','cybersecurity','Monitors, detects and responds to security threats.','يراقب التهديدات الأمنية ويكتشفها ويستجيب لها.',ARRAY['BSc Information Systems and Security','Information Systems and Security','BSc Computer Science'],'entry',ARRAY['Network Security','Incident Response','Risk Assessment','Operating Systems'],ARRAY['SIEM','Penetration Testing','Cryptography'],ARRAY['Attention to detail','Integrity','Communication'],ARRAY['Wireshark','Splunk','Kali Linux'],ARRAY['Network Security','Information Security','Operating Systems'],ARRAY['CompTIA Security+'],'Security internship or a documented lab environment.','Write-ups of security labs or CTF participation.',ARRAY['banking','government','technology'],ARRAY['cybersecurity','soc analyst','siem','security+','incident response'],true),
('IT_SUPPORT','IT Systems Administrator','مسؤول أنظمة تقنية المعلومات','information technology','Runs, secures and supports institutional IT infrastructure.','يشغّل ويؤمّن ويدعم البنية التحتية لتقنية المعلومات.',ARRAY['BSc Information Systems and Security','BSc Computer Science','Information Systems and Security'],'entry',ARRAY['Networking','Operating Systems','Troubleshooting'],ARRAY['Cloud Computing','Scripting','Active Directory'],ARRAY['Service orientation','Patience','Communication'],ARRAY['Linux','Windows Server','PowerShell'],ARRAY['Networking','Operating Systems','Information Systems'],ARRAY['CompTIA Network+'],'Helpdesk or campus IT experience is valued.','Documented home lab or automation scripts.',ARRAY['technology','education','government'],ARRAY['system administrator','it support','networking','linux'],true),
('BUSINESS_ANALYST','Business Analyst','محلل أعمال','business','Bridges business needs and technical delivery through analysis.','يربط احتياجات العمل بالتنفيذ التقني عبر التحليل.',ARRAY['Bachelor of Business Administration','BSc Information Systems and Security','Business Administration'],'entry',ARRAY['Requirements Analysis','Process Mapping','Excel','Reporting'],ARRAY['SQL','Stakeholder Management','Agile'],ARRAY['Communication','Critical thinking','Negotiation'],ARRAY['Excel','Jira','Visio','Power BI'],ARRAY['Management','Business Analysis','Statistics','Accounting'],ARRAY['IIBA ECBA'],'An internship in operations, consulting or a project team.','Two case studies with process diagrams.',ARRAY['banking','consulting','government'],ARRAY['business analyst','requirements','process improvement','stakeholder'],true),
('MARKETING_SPECIALIST','Marketing Specialist','أخصائي تسويق','business','Plans and runs marketing campaigns and brand communication.','يخطط وينفذ الحملات التسويقية والتواصل مع الجمهور.',ARRAY['Bachelor of Business Administration','Business Administration'],'entry',ARRAY['Marketing','Content Creation','Market Research'],ARRAY['Digital Marketing','Analytics','Copywriting'],ARRAY['Creativity','Communication','Teamwork'],ARRAY['Canva','Google Analytics','Meta Business Suite'],ARRAY['Marketing','Management','Communication'],ARRAY['Google Analytics Certification'],'Campus club, internship or freelance campaign experience.','A portfolio of campaigns or content samples.',ARRAY['retail','media','technology'],ARRAY['marketing','campaign','social media','seo','content'],true),
('FINANCIAL_ANALYST','Financial Analyst','محلل مالي','business','Analyses financial data to support budgeting and investment decisions.','يحلل البيانات المالية لدعم قرارات الميزانية والاستثمار.',ARRAY['Bachelor of Business Administration','Business Administration','BSc Mathematical Sciences'],'entry',ARRAY['Financial Analysis','Accounting','Excel','Statistics'],ARRAY['Valuation','Forecasting','SQL'],ARRAY['Attention to detail','Integrity','Analytical thinking'],ARRAY['Excel','Power BI','Bloomberg Terminal'],ARRAY['Accounting','Finance','Statistics','Mathematics'],ARRAY['CFA Level I'],'Internship in a bank, audit firm or finance department.','Financial models or investment memos.',ARRAY['banking','energy','government'],ARRAY['financial analyst','forecasting','valuation','excel','accounting'],true),
('ELECTRICAL_ENGINEER','Electrical Engineer','مهندس كهربائي','engineering','Designs and tests electrical systems, power and control equipment.','يصمم ويختبر الأنظمة الكهربائية ومعدات الطاقة والتحكم.',ARRAY['BSc Electrical Engineering','Electrical Engineering'],'entry',ARRAY['Circuit Design','Electronics','Control Systems','Physics'],ARRAY['Embedded Systems','Power Systems','Signal Processing'],ARRAY['Attention to detail','Safety awareness','Teamwork'],ARRAY['MATLAB','AutoCAD','LTspice'],ARRAY['General Physics','Circuits','Control Systems','Mathematics'],ARRAY['Engineer Licence (SOE)'],'Industrial training or a hardware capstone project.','Documented hardware builds with schematics.',ARRAY['energy','utilities','manufacturing'],ARRAY['electrical engineer','circuits','power systems','matlab','plc'],true),
('MECHANICAL_ENGINEER','Mechanical Engineer','مهندس ميكانيكي','engineering','Designs mechanical systems, components and manufacturing processes.','يصمم الأنظمة والمكونات الميكانيكية وعمليات التصنيع.',ARRAY['BSc Mechanical Engineering','Mechanical Engineering'],'entry',ARRAY['CAD','Thermodynamics','Mechanics','Physics'],ARRAY['Finite Element Analysis','Manufacturing','Materials'],ARRAY['Problem solving','Teamwork','Safety awareness'],ARRAY['SolidWorks','AutoCAD','ANSYS'],ARRAY['General Physics','Thermodynamics','Mechanics','Mathematics'],ARRAY['Engineer Licence (SOE)'],'Industrial training placement or a design competition team.','CAD models and a capstone design report.',ARRAY['manufacturing','energy','construction'],ARRAY['mechanical engineer','solidworks','cad','thermodynamics','ansys'],true),
('TEACHER','School Teacher','معلم','education','Plans lessons, teaches and assesses learning in schools.','يخطط الدروس ويقوم بالتدريس وتقييم التعلم في المدارس.',ARRAY['Bachelor of Education','Education','BSc Mathematical Sciences','BSc Biology'],'entry',ARRAY['Lesson Planning','Classroom Management','Assessment'],ARRAY['Educational Technology','Curriculum Design','Inclusive Education'],ARRAY['Communication','Patience','Empathy'],ARRAY['Microsoft Teams','Google Classroom'],ARRAY['Education','Psychology','Teaching Methods'],ARRAY['Teaching Licence (UAE)'],'Practicum or teaching practice placement.','A teaching portfolio with lesson plans and reflections.',ARRAY['education','government'],ARRAY['teacher','lesson planning','classroom','curriculum','assessment'],true),
('LAB_SCIENTIST','Laboratory Scientist','أخصائي مختبرات','science and research','Runs laboratory experiments, analysis and quality testing.','ينفذ التجارب المخبرية والتحاليل واختبارات الجودة.',ARRAY['BSc Biology','Biology'],'entry',ARRAY['Laboratory Techniques','Data Recording','Biology','Quality Control'],ARRAY['Microbiology','Biochemistry','Research Methods'],ARRAY['Attention to detail','Integrity','Teamwork'],ARRAY['Microscopy','SPSS','Excel'],ARRAY['Biology','Chemistry','Research Methods','Statistics'],ARRAY['Good Laboratory Practice'],'Research assistantship or laboratory internship.','Lab reports or a research poster.',ARRAY['healthcare','research','environment'],ARRAY['laboratory','research assistant','sample analysis','quality control'],true)
